<?php require_once 'config/database.php'; require_once 'includes/functions.php'; $page_title='Cart'; $items=cart_items($pdo); $totals=cart_totals($pdo); include 'includes/header.php'; ?>
<section class="page-banner"><div class="container"><div class="eyebrow">Almost there</div><h1>Your Cart</h1></div></section><section class="section"><div class="container"><?php if (!$items): ?><div class="empty"><h2>Your cart is empty.</h2><p class="muted">Pick something tasty from the menu.</p><a class="button" href="menu.php">Browse Menu</a></div><?php else: ?><table class="cart-table"><thead><tr><th>Item</th><th>Price</th><th>Quantity</th><th>Subtotal</th><th></th></tr></thead><tbody><?php foreach($items as $item): ?><tr id="cart-row-<?= $item['id'] ?>"><td data-label="Item"><div class="cart-food"><img src="<?= esc($item['image']) ?>" alt=""><strong><?= esc($item['food_name']) ?></strong></div></td><td data-label="Price">₹<?= number_format($item['price'],2) ?></td><td data-label="Quantity"><div class="qty-controls"><button onclick="changeQty(<?= $item['id'] ?>, <?= $item['quantity']-1 ?>)">-</button><span id="qty-<?= $item['id'] ?>"><?= $item['quantity'] ?></span><button onclick="changeQty(<?= $item['id'] ?>, <?= $item['quantity']+1 ?>)">+</button></div></td><td data-label="Subtotal" id="sub-<?= $item['id'] ?>">₹<?= number_format($item['subtotal'],2) ?></td><td><button class="secondary small" onclick="removeItem(<?= $item['id'] ?>)">Remove</button></td></tr><?php endforeach; ?></tbody></table><div class="summary"><div class="summary-row"><span>Subtotal</span><strong id="subtotal">₹<?= number_format($totals['subtotal'],2) ?></strong></div><div class="summary-row"><span>Delivery</span><strong id="delivery">₹<?= number_format($totals['delivery'],2) ?></strong></div><div class="summary-row summary-total"><span>Total</span><strong id="total">₹<?= number_format($totals['total'],2) ?></strong></div><a class="button" style="margin-top:16px" href="checkout.php">Proceed to Checkout</a></div><?php endif; ?></div></section><script>
async function changeQty(id, quantity) { if(quantity<1) return removeItem(id); const result=await postCart('update_cart',{food_id:id,quantity}); if(result.success){ document.querySelector('#qty-'+id).textContent=quantity; updateTotals(result.totals); } }
async function removeItem(id) { const result=await postCart('remove_cart',{food_id:id}); if(result.success){ document.querySelector('#cart-row-'+id).remove(); document.querySelector('#cart-count').textContent=result.count; updateTotals(result.totals); if(result.count===0) location.reload(); } }
function updateTotals(t){ document.querySelector('#subtotal').textContent='₹'+Number(t.subtotal).toFixed(2); document.querySelector('#delivery').textContent='₹'+Number(t.delivery).toFixed(2); document.querySelector('#total').textContent='₹'+Number(t.total).toFixed(2); }
</script><?php include 'includes/footer.php'; ?>